function shortestPathQueries(graph, start, queries) {
  const Q = new Queue();
  Q.push(start);
  const predecessors = new Map();
  predecessors.set(start, null);

  while (!Q.empty()) {
    const node = Q.pop();
    for (const nbr of graph[node]) {
      if (!predecessors.has(nbr)) {
        predecessors.set(nbr, node);
        Q.push(nbr);
      }
    }
  }

  const res = [];
  for (const node of queries) {
    if (!predecessors.has(node)) {
      res.push([]);
    } else {
      const path = [node];
      while (path[path.length - 1] !== start) {
        path.push(predecessors.get(path[path.length - 1]));
      }
      path.reverse();
      res.push(path);
    }
  }
  return res;
}

class QueueNode {
  constructor(val) {
    this.val = val;
    this.next = null;
  }
}

class Queue {
  constructor() {
    this.head = null;
    this.tail = null;
    this._size = 0;
  }

  empty() {
    return !this.head;
  }

  size() {
    return this._size;
  }

  push(val) {
    const newNode = new QueueNode(val);
    if (this.tail) {
      this.tail.next = newNode;
    }

    this.tail = newNode;
    if (!this.head) {
      this.head = newNode;
    }
    this._size++;
  }

  pop() {
    if (this.empty()) {
      throw new Error("empty queue");
    }
    const val = this.head.val;
    this.head = this.head.next;
    if (!this.head) {
      this.tail = null;
    }
    this._size--;
    return val;
  }
}

